import {icon,navigation,nav} from '/app/shell.js?v=4';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storage={get(k){try{return localStorage.getItem(k)}catch{return null}},set(k,v){try{localStorage.setItem(k,v);return true}catch{return false}}};
const prior=storage.get('ls-audience-v2');
const requestedAudience=new URLSearchParams(location.search).get('zielgruppe');
let audience=requestedAudience==='school'?'school':requestedAudience==='learner'?'learner':location.pathname.includes('/fahrschulen/')?'school':location.pathname.includes('/fahrschueler/')?'learner':prior==='school'?'school':'learner';
if(location.pathname.includes('/fahrschulen/')||location.pathname.includes('/fahrschueler/'))storage.set('ls-audience-v2',audience);
let filter='all',query='',view='entdecken',toastTimer;let saved=[];try{saved=JSON.parse(storage.get('ls-saved-v2')||'[]');if(!Array.isArray(saved))saved=[];}catch{}
const tools=[
{id:'konzept',title:'Kooperationskonzept',desc:'Versicherungscheck, Theoriebeitrag, Kooperation und Netzwerk im Detail.',href:'fahrschulen-informationen/',icon:'network',group:'school',label:'Bausteine ansehen'},
{id:'start',title:'Nach dem Führerschein',desc:'Orientierung zu Absicherung und dem Start in die eigene Mobilität.',href:'fahrschueler-informationen/',icon:'car',group:'learner',label:'Angebote ansehen'},
{id:'radar',title:'Gefahrenradar',desc:'Gefahren erkennen, schnell entscheiden und aus Situationen lernen.',href:'lernwelt/gefahrenradar/',icon:'radar',group:'learner',label:'Runde starten'},
{id:'kosten',title:'Fahrzeugkosten',desc:'Was kostet dein Auto im Monat? Rechne die laufenden Kosten zusammen.',href:'fahrzeugkosten/',icon:'car',group:'learner',label:'Kosten berechnen'},
{id:'lernen',title:'Lernwelt Klasse B',desc:'Wissen festigen und wechselnde Fragen für den Straßenverkehr üben.',href:'lernwelt/',icon:'book',group:'learner',label:'Lernen starten'},
{id:'easi',title:'EaSI Drive',desc:'Eine Vertragslösung für junge Fahrer:innen verstehen.',href:'easi-drive/',icon:'shield',group:'learner',label:'Lösung ansehen'},
{id:'unfall',title:'Unfallhelfer',desc:'Nach einem Unfall die nächsten Schritte im Blick behalten.',href:'unfallhelfer/',icon:'shield',group:'learner',label:'Unfallhelfer öffnen'},
{id:'check',title:'5-Minuten-Check',desc:'Mit zwölf Fragen den Schutz Ihres Betriebs strukturiert einordnen.',href:'fahrschul-check/',icon:'check',group:'school',label:'Check starten'},
{id:'cockpit',title:'Fahrschul-Cockpit',desc:'Betrieb, Team, Fuhrpark und Absicherung an einem Ort.',href:'cockpit/',icon:'tools',group:'school',label:'Cockpit öffnen'},
{id:'vorlagen',title:'Vorlagen',desc:'Checks, Notfallkarten und Protokolle für Ihren Fahrschulalltag.',href:'vorlagen/',icon:'file',group:'school',label:'Vorlagen ansehen'},
{id:'notfall',title:'Notfallcenter',desc:'Strukturierte Erstschritte für betriebliche Notfälle.',href:'notfallcenter/',icon:'shield',group:'school',label:'Notfallcenter öffnen'}];
const url=p=>'/konzept/'+p;
const action=(href,label,type='primary')=>`<a class="${type}" href="${href}"><span class="action-label">${label}</span>${icon('arrow')}</a>`;
const posts=[
{id:'radar',category:'tools',groups:['learner'],meta:'Lernwelt · 60–90 Sekunden',tag:'Ausprobieren',art:()=>`<div class="feature-art"><p class="eyebrow">Dein Blick macht den Unterschied</p><h2>Gefahr erkannt.<br>Rechtzeitig reagiert?</h2><p class="art-note">Eine kurze Runde. Situationen, die zählen.</p><div class="radar-art" aria-label="Verkehrsszene aus dem Gefahrenradar"></div></div>`,title:'Trainiere deinen Blick für die Straße.',body:'Was könnte als Nächstes passieren? Entdecke mögliche Gefahren und entscheide, bevor es kritisch wird.',href:'lernwelt/gefahrenradar/',cta:'Gefahrenradar starten'},
{id:'emre',category:'network',groups:['learner','school'],meta:'Kooperation · Herne & Recklinghausen',tag:'Im Netzwerk',art:()=>`<div class="cooperation-art"><div class="copy"><p class="eyebrow">LANE SWITCH × Emre</p><h2>Zusammen<br>eine Spur<br>weiter.</h2><p>Fahrschule Emre ist mit dabei.</p></div><img src="${url('assets/kooperationen/emre-poster.jpg')}" alt="Originalmotiv zur Kooperation mit Fahrschule Emre" width="540" height="960" loading="lazy"></div>`,title:'Die erste Kooperation steht.',body:'Lerne Fahrschule Emre kennen: Standorte, Führerscheinklassen und das gemeinsame Video an einem Ort.',href:'kooperationen/fahrschulen/fahrschule-emre/',cta:'Emre kennenlernen'},
{id:'check',category:'tools',groups:['school'],meta:'Für Ihren Betrieb · 5 Minuten',tag:'Betriebscheck',art:()=>`<div class="school-art"><p class="eyebrow">Mehr Überblick im Fahrschulalltag</p><h2>Sie bringen andere weiter.<br>Wer schaut auf Ihren Betrieb?</h2><ul><li>${icon('check')}Betrieb und Fuhrpark</li><li>${icon('check')}Team und Inhaberabsicherung</li><li>${icon('check')}Risiken und nächste Schritte</li></ul></div>`,title:'Zwölf Fragen. Ein erster Überblick.',body:'Der Fahrschul-Check hilft, offene Themen sichtbar zu machen. Das Ergebnis kann die Grundlage für ein persönliches Gespräch sein.',href:'fahrschul-check/',cta:'5-Minuten-Check starten'},
{id:'easi',category:'tools',groups:['learner'],meta:'Orientierung · Erstes Auto',tag:'EaSI Drive',art:()=>`<div class="price-art"><div><p class="eyebrow">EaSI-Drive-Vertrag</p><h2>349,90 €</h2><p>jährlicher Vertragsbeitrag</p></div>${icon('car')}</div>`,title:'Das Auto der Eltern. Deine Mobilität.',body:'Wie funktioniert EaSI Drive? Erfahre mehr über die Vertragslösung und die Musterberechnung. Der Fahrzeugvertrag kommt zusätzlich hinzu.',href:'easi-drive/',cta:'EaSI Drive verstehen'},
{id:'instagram',category:'social',groups:['learner','school'],meta:'Instagram · Ausgewählter Beitrag',tag:'Social',art:null,title:'Die erste Spur ist gewechselt.',body:'Unsere Ankündigung der Kooperation mit Fahrschule Emre. Den Originalbeitrag findest du auf Instagram.',external:'https://www.instagram.com/p/DdBhSA0uYvy/',cta:'Beitrag auf Instagram öffnen'}
];
function postCard(original){const p={...original};if(audience==='school'&&p.id==='emre'){p.title='So sieht Zusammenarbeit vor Ort aus.';p.body='Fahrschule Emre ist unser erster Kooperationspartner. Erfahren Sie mehr über die Zusammenarbeit und lernen Sie die Fahrschule kennen.';p.cta='Kooperation ansehen';}else if(audience==='learner'&&p.id==='emre'){p.title='Lerne Fahrschule Emre kennen.';p.body='Standorte, Führerscheinklassen und Ansprechpartner: Hier findest du die Infos zur Fahrschule Emre.';}if(p.id==='instagram')p.body=audience==='school'?'Unsere erste Fahrschulkooperation: die Ankündigung mit Fahrschule Emre auf Instagram.':'Fahrschule Emre kennenlernen: unsere gemeinsame Ankündigung auf Instagram.';return `<article class="post" data-post="${p.id}"><div class="post-top"><div class="avatar"><img src="${url('assets/logo-symbol.svg')}" width="34" height="34" alt=""></div><div><p class="post-author">LANE SWITCH</p><p class="post-meta">${p.meta}</p></div><span class="post-tag">${p.tag}</span></div>${p.art?p.art():''}<div class="post-copy"><h2>${p.title}</h2><p>${p.body}</p><div class="post-actions"><a class="primary" href="${p.external||url(p.href)}" ${p.external?'target="_blank" rel="noopener noreferrer"':''}><span class="action-label">${p.cta}</span>${icon(p.external?'external':'arrow')}</a><button class="save" data-save="${p.id}" aria-pressed="${saved.includes(p.id)}" aria-label="${saved.includes(p.id)?'Nicht mehr merken':'Beitrag merken'}: ${esc(original.title)}">${icon('bookmark')}</button></div></div></article>`}
function intro(k,h,p){return `<div class="intro"><p class="eyebrow">${k}</p><h1>${h}</h1><p>${p}</p></div>`}
function updates(){const school=audience==='school';const items=school?[
 ['network','Kooperation vor Ort','Fahrschule Emre im Netzwerk','kooperationen/fahrschulen/fahrschule-emre/'],
 ['file','Für Ihren Alltag','Vorlagen für den Betrieb','vorlagen/'],
 ['check','Schutz einordnen','5-Minuten-Fahrschulcheck','fahrschul-check/']
]:[
 ['network','Fahrschule kennenlernen','Emre: Standorte & Klassen','kooperationen/fahrschulen/fahrschule-emre/'],
 ['radar','Für deinen Blick','Gefahrenradar ausprobieren','lernwelt/gefahrenradar/'],
 ['car','Für dein erstes Auto','Autokosten berechnen','fahrzeugkosten/']
];return `<div class="section-row"><h2>Was gibt’s Neues?</h2><span class="post-meta">Wischen & entdecken</span></div><div class="updates" aria-label="Neuigkeiten">${items.map(([i,k,t,h])=>`<a class="update" href="${url(h)}"><span class="update-icon">${icon(i)}</span><span><small>${k}</small><strong>${t}</strong></span></a>`).join('')}</div>`}
function renderFeed(){const school=audience==='school';let list=posts.filter(p=>p.groups.includes(audience));if(school)list.sort((a,b)=>(a.id==='check'?-1:b.id==='check'?1:0));if(filter==='saved')list=list.filter(p=>saved.includes(p.id));else if(filter!=='all')list=list.filter(p=>p.category===filter);document.getElementById('view').innerHTML=intro(school?'Für Fahrlehrer:innen & Fahrschulen':'Für deinen Start in die Mobilität',school?'Mehr Zeit fürs<br>Wesentliche.':'Dein nächster Schritt.<br>Gut begleitet.',school?'Praktische Hilfe für Ihren Betrieb. Neue Impulse für Ihren Unterricht.':'Wissen, das dich weiterbringt. Werkzeuge, die dir den Start erleichtern.')+updates()+`<div class="section-row feed-title"><h2>${school?'Ihr Update':'Dein Update'}</h2></div><div class="feed-filters" role="group" aria-label="Feed filtern">${[['all',school?'Für Sie':'Für dich'],['tools','Angebote'],['network','Netzwerk'],['social','Instagram'],['saved','Gemerkt']].map(([id,label])=>`<button class="chip" data-filter="${id}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div><div class="feed">${list.length?list.map(postCard).join(''):'<div class="empty"><h2>Noch nichts gemerkt.</h2><p>Tippe auf das Lesezeichen an einem Beitrag. Deine Auswahl wird nur auf diesem Gerät gespeichert.</p></div>'}</div><div class="feed-end"><p>Deine nächste gute Idee wartet schon.</p><a href="https://www.instagram.com/laneswitch.de/" target="_blank" rel="noopener noreferrer">Mehr auf Instagram ${icon('external')}</a></div>`;renderRadar();}
async function renderRadar(){const el=document.querySelector('.radar-art');if(!el)return;try{const [a,b]=await Promise.all([import('/konzept/lernwelt/gefahrenradar/scenes.mjs'),import('/konzept/lernwelt/gefahrenradar/illustrations.mjs')]);if(!el.isConnected)return;el.innerHTML=b.illustration(a.SCENES[0],'feed');b.paint(el,a.SCENES[0],a.SCENES[0].cueMs+2200);}catch{el.innerHTML='<p style="padding:24px;color:#092d46">Gefahrenradar direkt öffnen und die Szene spielen.</p>'}}
function toolCards(){const list=tools.filter(t=>t.group===audience).filter(t=>(t.title+' '+t.desc).toLocaleLowerCase('de').includes(query.toLocaleLowerCase('de')));document.getElementById('tool-results').innerHTML=list.length?`<div class="tool-grid">${list.map(t=>`<a class="tool-card" href="${url(t.href)}"><span class="update-icon">${icon(t.icon)}</span><p class="eyebrow">${t.group==='school'?'Fahrschulen':'Fahrschüler:innen'}</p><h2>${t.title}</h2><p>${t.desc}</p><span class="small-link"><span class="action-label">${t.label}</span>${icon('arrow')}</span></a>`).join('')}</div>`:'<div class="empty">Kein Werkzeug gefunden. Probiere einen anderen Suchbegriff.</div>';document.getElementById('search-count').textContent=`${list.length} ${list.length===1?'Werkzeug':'Werkzeuge'}`;}
function renderTools(){document.getElementById('view').innerHTML=intro('Direkt loslegen','Weniger suchen.<br>Mehr weiterkommen.',audience==='school'?'Arbeitshilfen für Ihren Betrieb, Ihr Team und die Zusammenarbeit.':'Deine Werkzeuge für Theorie, Straßenverkehr und das erste Auto.')+`<div class="search"><label class="sr-only" for="tool-search">Werkzeuge suchen</label>${icon('search')}<input id="tool-search" type="search" placeholder="Werkzeug suchen …" value="${esc(query)}" autocomplete="off" aria-controls="tool-results"></div><div class="section-row"><h2>Wissen & Werkzeuge</h2><span id="search-count" class="post-meta" role="status"></span></div><div id="tool-results"></div>`;toolCards();}
function renderNetwork(){const school=audience==='school';document.getElementById('view').innerHTML=intro(school?'Zusammenarbeit in der Region':'Fahrschulen in deiner Nähe',school?'Gemeinsam<br>weiterkommen.':'Deine Fahrschule.<br>Gut vernetzt.',school?'Lernen Sie unser Fahrschulnetzwerk und die Möglichkeiten einer Kooperation kennen.':'Entdecke unsere Partnerfahrschulen und finde ihre Standorte, Führerscheinklassen und Kontakte.')+`<article class="post network-card"><div class="network-layout"><video controls playsinline preload="none" poster="${url('assets/kooperationen/emre-poster.jpg')}" aria-label="Kooperation von LANE SWITCH und Fahrschule Emre"><source src="${url('assets/kooperationen/emre-kooperation-web.mp4')}" type="video/mp4"></video><div class="post-copy"><p class="eyebrow">${school?'Unser erster Fahrschulpartner':'Im LANE-SWITCH-Netzwerk'}</p><h2>Fahrschule<br>Emre.</h2><p>Herne & Recklinghausen</p><p style="margin-top:18px">${school?'Ein Einblick in unsere erste Kooperation und die gemeinsame Vorstellung.':'Alle Standorte, Führerscheinklassen und Kontaktmöglichkeiten im Überblick.'}</p><div class="post-actions">${action(url('kooperationen/fahrschulen/fahrschule-emre/'),school?'Kooperation ansehen':'Zur Fahrschule')}</div></div></div></article><div class="contact-card" style="margin-top:22px"><p class="eyebrow">${school?'Für Fahrschulen & Netzwerkpartner':'Nach dem Führerschein'}</p><h2>${school?'Passt Ihr Betrieb dazu?':'Bereit für dein erstes Auto?'}</h2><p>${school?'Versicherungscheck, Theoriebeitrag und Netzwerk: Gemeinsam finden wir heraus, welche Bausteine sinnvoll sind.':'Verschaffe dir einen Überblick über die laufenden Fahrzeugkosten und plane deinen Start in die eigene Mobilität.'}</p>${action(school?'#kontakt':url('fahrzeugkosten/'),school?'Kooperation besprechen':'Autokosten berechnen')}</div>`;}
const contactDrafts={learner:{},school:{}};
if(new URLSearchParams(location.search).get('anliegen')==='fahrschul-check'){audience='school';storage.set('ls-audience-v2',audience);contactDrafts.school={topic:'Ergebnis des Fahrschul-Checks besprechen',message:'Ich möchte mein Ergebnis aus dem Fahrschul-Check gemeinsam einordnen.'};}
const contactTopics={learner:['Allgemeine Frage','Unfallabsicherung und erstes Auto','EaSI Drive','Fahrzeugkosten','Lernwelt und Gefahrenradar'],school:['20-Minuten-Kennenlernen','Versicherungscheck für die Fahrschule','Ergebnis des Fahrschul-Checks besprechen','Theoriebeitrag und Quiz','Tippgeberkooperation','Netzwerk und ergänzende Lösungen']};
function renderContact(){const school=audience==='school',draft=contactDrafts[audience];const field=(name)=>esc(draft[name]||'');document.getElementById('view').innerHTML=intro('Direkt eine Anfrage vorbereiten',school?'Was können wir<br>für Sie tun?':'Was möchtest<br>du wissen?',school?'Ihre Anfrage zu Betrieb, Unterricht oder Zusammenarbeit.':'Deine Frage zum ersten Auto, zur Absicherung oder zu unseren Lernangeboten.')+`<form class="inquiry-form" id="inquiry-form"><div class="form-grid"><label><span>Name *</span><input name="name" autocomplete="name" required value="${field('name')}"></label><label><span>E-Mail-Adresse</span><input name="email" type="email" autocomplete="email" value="${field('email')}"></label></div>${school?`<label><span>Fahrschule oder Unternehmen</span><input name="school" autocomplete="organization" value="${field('school')}"></label>`:''}<label><span>Telefonnummer <small>(optional)</small></span><input name="phone" type="tel" autocomplete="tel" value="${field('phone')}"></label><label><span>${school?'Ihr Anliegen':'Dein Anliegen'}</span><select name="topic">${contactTopics[audience].map(t=>`<option ${draft.topic===t?'selected':''}>${t}</option>`).join('')}</select></label><label><span>Nachricht</span><textarea name="message" rows="4" placeholder="${school?'Wobei können wir Sie unterstützen?':'Wobei können wir dir helfen?'}">${field('message')}</textarea></label><label class="form-consent"><input name="consent" type="checkbox" required ${draft.consent?'checked':''}><span>Ich habe die <a href="${url('datenschutz/')}" target="_blank" rel="noopener">Datenschutzhinweise</a> gelesen. Bitte keine Gesundheits-, Vertrags- oder Bankdaten eintragen.</span></label><button class="primary" type="submit"><span class="action-label">E-Mail-Programm öffnen</span>${icon('arrow')}</button><p class="form-caption">Öffnet dein E-Mail-Programm mit der ausgefüllten Anfrage. Dort prüfst du die Nachricht und sendest sie selbst ab.</p><p class="form-caption">Kein automatischer Versand. Deine Formulareingaben bleiben bis zum Öffnen des E-Mail-Programms in dieser Browserseite und werden nicht dauerhaft gespeichert.</p></form><div class="contact-person-inline"><span class="initials" aria-hidden="true">SD</span><div><h2>Steven Dragojevic</h2><p>${school?'Ihr Ansprechpartner':'Dein Ansprechpartner'} bei LANE SWITCH</p></div></div><div class="contact-info"><a href="tel:+491727937262">${icon('phone')}0172 7937262</a><a href="mailto:kontakt@laneswitch.de">${icon('mail')}kontakt@laneswitch.de</a></div><p class="legal-note">Steven Dragojevic ist angestellter Mitarbeiter im Versicherungsvertrieb der SIGNAL IDUNA Allgemeine Versicherung Aktiengesellschaft. Versicherungsberatung und Vermittlung erfolgen im Rahmen dieser Tätigkeit. Es findet kein unabhängiger Marktvergleich statt. Kontakt und Abschluss sind freiwillig. <a href="https://signal-iduna-agentur.de/steven.dragojevic/" target="_blank" rel="noopener noreferrer">Erstinformation und Vermittlerangaben ↗</a></p>`;}
function inquiryMessage(data,group){
 const value=k=>String(data.get(k)||'').trim();
 const role=group==='school'?'Fahrschule / Fahrlehrer:in':'Fahrschüler:in';
 const topic=value('topic').replace(/[\r\n]+/g,' ');
 const subject='LANE SWITCH – '+topic;
 const lines=['Rolle: '+role,'Name: '+value('name'),'E-Mail: '+value('email'),'Telefon: '+value('phone')];
 if(group==='school')lines.push('Fahrschule: '+value('school'));
 lines.push('Anliegen: '+topic,'','Nachricht:',value('message'));
 const body=lines.join('\r\n');
 return {subject,body,copy:'An: kontakt@laneswitch.de\nBetreff: '+subject+'\n\n'+body,href:'mailto:kontakt@laneswitch.de?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body)};
}
function showInquiry(form){
 const name=form.elements.namedItem('name');
 name.setCustomValidity(name.value.trim()?'':'Bitte gib deinen Namen ein.');
 if(!form.reportValidity())return;
 const message=inquiryMessage(new FormData(form),audience);
 document.getElementById('inquiry-handoff')?.remove();
 const panel=document.createElement('section');
 panel.id='inquiry-handoff';panel.className='contact-card';panel.style.marginTop='20px';
 panel.innerHTML='<h2>Anfrage im E-Mail-Programm senden</h2><p tabindex="-1" role="status" id="inquiry-status">Die Anfrage ist noch nicht gesendet. Prüfe sie in deinem E-Mail-Programm und sende sie dort ab. Falls sich kein Programm öffnet, kopiere den Text in eine E-Mail an kontakt@laneswitch.de.</p><label for="inquiry-copy-text">Deine vorbereitete E-Mail</label><textarea id="inquiry-copy-text" readonly rows="10" style="width:100%;max-width:100%;box-sizing:border-box;margin:12px 0;padding:12px;border:1px solid var(--line,#b8cbd4);border-radius:12px;background:var(--card,#fff);color:var(--ink,#092d46);font:inherit"></textarea><div class="post-actions"><a class="secondary" id="inquiry-open">E-Mail erneut öffnen</a><button class="secondary" type="button" id="inquiry-copy">Anfrage kopieren</button></div>';
 const text=panel.querySelector('textarea');text.value=message.copy;
 panel.querySelector('#inquiry-open').href=message.href;
 panel.querySelector('#inquiry-copy').onclick=async()=>{
  try{await navigator.clipboard.writeText(message.copy);panel.querySelector('#inquiry-status').textContent='Anfrage kopiert. Füge sie in eine E-Mail an kontakt@laneswitch.de ein und sende sie dort ab.';}
  catch{text.focus();text.select();panel.querySelector('#inquiry-status').textContent='Bitte den markierten Text kopieren und in deine E-Mail einfügen.';}
 };
 form.after(panel);panel.querySelector('#inquiry-status').focus({preventScroll:true});
 try{window.location.href=message.href;}catch{panel.querySelector('#inquiry-status').textContent='Das E-Mail-Programm konnte nicht geöffnet werden. Kopiere die Anfrage und sende sie an kontakt@laneswitch.de.';}
}
function openRecommend(){let target=audience;document.getElementById('recommend-app')?.remove();const d=document.createElement('dialog');d.id='recommend-app';d.setAttribute('aria-labelledby','recommend-title');d.innerHTML=`<div class="dialog-head"><h2 id="recommend-title">LANE SWITCH empfehlen</h2><button class="icon-button" id="recommend-close" aria-label="Empfehlung schließen">×</button></div><div class="dialog-body"><p>Für wen ist deine Empfehlung?</p><div class="audience recommend-targets" role="group" aria-label="Zielgruppe der Empfehlung"><button data-recommend-target="learner">Fahrschüler:innen</button><button data-recommend-target="school">Fahrschulen</button></div><p id="share-preview" class="share-preview"></p><div class="share-actions"><button class="primary" id="share-native">Teilen</button><a class="secondary" id="share-whatsapp" target="_blank" rel="noopener noreferrer">WhatsApp</a><button class="secondary" id="share-copy">Link kopieren</button></div><p class="form-caption">Die Empfehlung führt zur bestehenden öffentlichen Website auf laneswitch.de. Erst die gewählte App übernimmt den Versand.</p></div>`;const shareData=()=>({title:'LANE SWITCH',url:'https://laneswitch.de/'+(target==='school'?'fahrschulen/':'fahrschueler/'),text:target==='school'?'Ich möchte Ihnen LANE SWITCH empfehlen: ein Partnerkonzept mit Versicherungscheck, Theoriebeitrag und praktischen Arbeitshilfen für Fahrschulen.':'Schau dir LANE SWITCH an: Gefahrenradar, Lernwelt und Fahrzeugkosten-Rechner für deinen Start in die eigene Mobilität.'});const update=()=>{const data=shareData();d.querySelector('#share-preview').textContent=data.text;d.querySelectorAll('[data-recommend-target]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.recommendTarget===target)));d.querySelector('#share-whatsapp').href='https://wa.me/?text='+encodeURIComponent(data.text+' '+data.url)};d.querySelectorAll('[data-recommend-target]').forEach(b=>b.onclick=()=>{target=b.dataset.recommendTarget;update()});d.querySelector('#recommend-close').onclick=()=>d.close();d.querySelector('#share-copy').onclick=async()=>{try{await navigator.clipboard.writeText(shareData().url);d.querySelector('#share-copy').textContent='Link kopiert';}catch{d.querySelector('#share-preview').textContent=shareData().text+' '+shareData().url;d.querySelector('#share-copy').textContent='Link oben markieren';}};d.querySelector('#share-native').onclick=async()=>{const data=shareData();if(navigator.share){try{await navigator.share(data)}catch(e){if(e.name!=='AbortError')d.querySelector('#share-preview').textContent=data.text+' '+data.url;}}else{try{await navigator.clipboard.writeText(data.text+' '+data.url);d.querySelector('#share-native').textContent='Empfehlung kopiert';}catch{d.querySelector('#share-preview').textContent=data.text+' '+data.url;}}};d.addEventListener('close',()=>d.remove());document.body.append(d);update();d.showModal();}
function renderRail(){const list=tools.filter(t=>t.group===audience&&!['konzept','start'].includes(t.id)).slice(0,3);document.getElementById('rail').innerHTML=`<section class="rail-card"><p class="eyebrow">Deine Abkürzung</p><h2>Direkt zum Ziel</h2>${list.map(t=>`<a class="tool-short" href="${url(t.href)}">${icon(t.icon)}<span><strong>${t.title}</strong><small>${t.label}</small></span></a>`).join('')}<a class="small-link" href="#werkzeuge">Alle Werkzeuge ${icon('arrow')}</a></section><section class="rail-card rail-help"><h2>${audience==='school'?'Was bewegt Ihren Betrieb?':'Noch eine Frage offen?'}</h2><p>${audience==='school'?'Gemeinsam schauen, welche Unterstützung zu Ihrer Fahrschule passt.':'Von der Fahrschule zum ersten Auto. Steven hilft dir beim nächsten Schritt.'}</p>${action('#kontakt','Kontakt aufnehmen','primary accent')}</section><section class="rail-card"><h2>Einfach umschalten.</h2><p class="subtle">Fahrschule oder Fahrschüler:in? Oben kannst du jederzeit die Perspektive wechseln.</p></section>`;}
function render(){const shortcut=document.getElementById('audience-shortcut');if(shortcut){shortcut.href=url(audience==='school'?'notfallcenter/':'unfallhelfer/');shortcut.innerHTML=icon('shield')+(audience==='school'?'Notfallcenter':'Unfallhelfer');}document.querySelectorAll('[data-audience]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.audience===audience)));document.querySelectorAll('[data-navigation]').forEach(n=>n.innerHTML=navigation(view));({entdecken:renderFeed,werkzeuge:renderTools,netzwerk:renderNetwork,kontakt:renderContact}[view]||renderFeed)();renderRail();document.title='LANE SWITCH · '+(nav.find(n=>n[0]===view)?.[2]||'Entdecken');}
function route(){const id=location.hash.slice(1)||(location.pathname.includes('/kontakt/')?'kontakt':'');view=nav.some(n=>n[0]===id)?id:'entdecken';render();window.scrollTo({top:0,behavior:'instant'});if(id==='empfehlen')openRecommend();}
function toast(text){clearTimeout(toastTimer);const el=document.getElementById('toast');el.textContent=text;el.hidden=false;toastTimer=setTimeout(()=>el.hidden=true,3500)}
function choose(value){audience=value;storage.set('ls-audience-v2',audience);filter='all';query='';render();}
function theme(){const dark=document.documentElement.dataset.theme==='dark';const b=document.getElementById('theme');b.innerHTML=icon(dark?'sun':'moon');b.setAttribute('aria-label',dark?'Hellen Modus aktivieren':'Dunklen Modus aktivieren');b.setAttribute('aria-pressed',String(dark));}
document.documentElement.dataset.theme=storage.get('laneswitch-theme-v1')==='dark'?'dark':'light';theme();
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
document.getElementById('theme').addEventListener('click',()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';storage.set('laneswitch-theme-v1',document.documentElement.dataset.theme);theme()});
document.addEventListener('click',e=>{if(e.target.closest('[data-recommend]')){openRecommend();return}const audienceButton=e.target.closest('[data-audience]');if(audienceButton){choose(audienceButton.dataset.audience);toast(audience==='school'?'Ansicht für Fahrlehrer:innen und Fahrschulen':'Ansicht für Fahrschüler:innen');return}const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;renderFeed();document.querySelector(`[data-filter="${filter}"]`)?.focus({preventScroll:true});return}const s=e.target.closest('[data-save]');if(s){const id=s.dataset.save;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];const persisted=storage.set('ls-saved-v2',JSON.stringify(saved));s.setAttribute('aria-pressed',String(saved.includes(id)));s.setAttribute('aria-label',(saved.includes(id)?'Nicht mehr merken':'Beitrag merken')+': '+posts.find(p=>p.id===id).title);toast(saved.includes(id)?(persisted?'Auf diesem Gerät gemerkt':'Für diese Sitzung gemerkt'):'Aus deiner Merkliste entfernt');if(filter==='saved')renderFeed();return}if(e.target.closest('[data-concept]'))document.getElementById('concept-dialog').showModal();});
document.addEventListener('input',e=>{if(e.target.id==='tool-search'){query=e.target.value;toolCards()}if(e.target.closest('#inquiry-form')&&e.target.name==='name')e.target.setCustomValidity('');if(e.target.closest('#inquiry-form')&&e.target.name)contactDrafts[audience][e.target.name]=e.target.type==='checkbox'?e.target.checked:e.target.value;});
document.addEventListener('submit',e=>{if(e.target.id==='inquiry-form'){e.preventDefault();showInquiry(e.target)}});
const dialog=document.getElementById('concept-dialog');document.getElementById('close-concept').onclick=()=>dialog.close();document.getElementById('concept-done').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
window.addEventListener('hashchange',route);route();
// First-visit choice, with a permanent switch in the main interface.
if(!prior&&!location.pathname.includes('/kontakt/')&&!location.hash&&!location.pathname.includes('/fahrschulen/')&&!location.pathname.includes('/fahrschueler/')){const welcome=document.createElement('dialog');welcome.id='welcome';welcome.setAttribute('aria-labelledby','welcome-title');welcome.innerHTML=`<div class="welcome"><img src="${url('assets/logo-primary.svg')}" class="logo-light" alt="LANE SWITCH" width="180"><img src="${url('assets/logo-primary-dark.svg')}" class="logo-dark" alt="LANE SWITCH" width="180"><p class="eyebrow">Schön, dass du da bist</p><h1 id="welcome-title">Was bringt dich<br>zu uns?</h1><p>Wähle deinen Einstieg. Du kannst die Ansicht jederzeit wechseln.</p><button class="welcome-choice" data-choice="learner"><span class="update-icon">${icon('car')}</span><span><strong>Ich mache den Führerschein</strong><small>Wissen, erstes Auto & sicher unterwegs</small></span>${icon('arrow')}</button><button class="welcome-choice" data-choice="school"><span class="update-icon">${icon('network')}</span><span><strong>Ich bin Fahrlehrer:in oder<br>betreibe eine Fahrschule</strong><small>Betrieb, Unterricht & Zusammenarbeit</small></span>${icon('arrow')}</button><button class="welcome-skip" id="welcome-skip">Erst einmal umsehen</button><p class="welcome-note">Deine Auswahl wird nur auf diesem Gerät gespeichert.</p></div>`;document.body.append(welcome);welcome.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{choose(b.dataset.choice);welcome.close();welcome.remove();document.querySelector(`[data-audience="${audience}"]`).focus({preventScroll:true});});welcome.querySelector('#welcome-skip').onclick=()=>{welcome.close();welcome.remove()};welcome.showModal();}
